<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.2);
      --text: #e2e8f0;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --accent-strong: #0ea5e9;
      --error: #fda4af;
      --error-strong: #fb7185;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.16), transparent 35%),
        linear-gradient(180deg, #020617 0%, var(--bg) 100%);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.9rem, 4vw, 2.4rem);
    }

    .intro {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 700;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.26);
      border-radius: 12px;
      background: rgba(15, 23, 42, 0.7);
      color: var(--text);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.18);
      background: rgba(15, 23, 42, 0.9);
    }

    input[aria-invalid="true"] {
      border-color: var(--error-strong);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .error-message {
      min-height: 1.1em;
      color: var(--error);
      font-size: 0.92rem;
    }

    button {
      margin-top: 6px;
      padding: 14px 18px;
      border: 0;
      border-radius: 12px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #e0f2fe;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 18px 36px rgba(14, 165, 233, 0.28);
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.05);
    }

    button:focus-visible {
      outline: 3px solid rgba(56, 189, 248, 0.45);
      outline-offset: 3px;
    }

    .success-message {
      margin: 0;
      color: #86efac;
      font-weight: 700;
      min-height: 1.2em;
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact Support</h1>
    <p class="intro">Send us your details and our support team will get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input
          id="full-name"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jordan Lee"
          required
          aria-describedby="full-name-error"
        >
        <p class="error-message" id="full-name-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jordan@example.com"
          required
          aria-describedby="email-error"
        >
        <p class="error-message" id="email-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phone-help phone-error"
        >
        <p class="helper-text" id="phone-help">Optional. Use digits only or common separators such as spaces, dashes, or parentheses, for example: (555) 123-4567.</p>
        <p class="error-message" id="phone-error" aria-live="polite"></p>
      </div>

      <button type="submit">Submit</button>
      <p class="success-message" id="success-message" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const successMessage = document.getElementById('success-message');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Full name is required.';
          }
          if (value.trim().length < 2) {
            return 'Enter your full name.';
          }
          return '';
        }
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Email address is required.';
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return 'Enter a valid email address.';
          }
          return '';
        }
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error'),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return '';
          }
          const phonePattern = /^\+?[0-9\s\-()]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return 'Use a valid phone number format.';
          }
          return '';
        }
      }
    };

    function showError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      showError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener('input', () => {
        validateField(field);
        if (successMessage.textContent) {
          successMessage.textContent = '';
        }
      });
      field.input.addEventListener('blur', () => validateField(field));
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      successMessage.textContent = '';

      const firstInvalidField = Object.values(fields).find((field) => !validateField(field));

      if (firstInvalidField) {
        firstInvalidField.input.focus();
        return;
      }

      successMessage.textContent = 'Your message details are ready to send.';
      form.reset();
      Object.values(fields).forEach((field) => showError(field, ''));
    });
  </script>
</body>
</html>
